def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the solid separator row or column, then compare the two equal-sized panels.
    candidates = []
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            left, right = [row[:c] for row in grid], [row[c+1:] for row in grid]
            if left and len(left[0]) == len(right[0]):
                candidates.append((left, right))
    for r in range(h):
        if all(x == grid[r][0] for x in grid[r]):
            top, bottom = grid[:r], grid[r+1:]
            if top and len(top) == len(bottom):
                candidates.append((top, bottom))
    if not candidates:
        raise ValueError("No centered solid separator with equal panels found")
    a, b = candidates[0]
    colors_a = {x for row in a for x in row}
    colors_b = {x for row in b for x in row}
    shared = colors_a & colors_b
    # The demonstrations have one shared panel color; highlight its cellwise matches.
    base = min(shared) if shared else 0
    return [[3 if a[r][c] == base and b[r][c] == base else base
             for c in range(len(a[0]))] for r in range(len(a))]
